class StageStatus(Enum):
    PENDING = auto()
    RUNNING = auto()
    COMPLETED = auto()
    FAILED = auto()


@dataclass
class StageResult:
    status: StageStatus
    data: Any = None
    error: Optional[str] = None


class DataStage(ABC):
    """Abstract base class for data processing stages."""

    def __init__(self, name: str):
        self.name = name
        self.status = StageStatus.PENDING

    @abstractmethod
    def execute(self, input_data: Any) -> StageResult:
        """Execute the stage with the given input data."""
        pass

    def reset(self):
        """Reset the stage status."""
        self.status = StageStatus.PENDING


class IngestionStage(DataStage):
    """Data ingestion module supporting CSV, Excel, and database sources."""

    def __init__(self):
        super().__init__("Ingestion")

    def execute(self, input_data: Any) -> StageResult:
        """Ingest data from various sources."""
        try:
            if isinstance(input_data, pd.DataFrame):
                # Already a DataFrame, use as-is
                return StageResult(status=StageStatus.COMPLETED, data=input_data)

            elif isinstance(input_data, str):
                # Assume it's a file path
                if input_data.endswith('.csv'):
                    df = pd.read_csv(input_data)
                elif input_data.endswith(('.xlsx', '.xls')):
                    df = pd.read_excel(input_data)
                else:
                    raise ValueError(f"Unsupported file format: {input_data}")

                # Validate format (basic check: non-empty and has columns)
                if df.empty:
                    raise ValueError("Ingested data is empty.")
                if len(df.columns) == 0:
                    raise ValueError("Ingested data has no columns.")

                return StageResult(status=StageStatus.COMPLETED, data=df)

            elif isinstance(input_data, dict):
                # Assume it's raw data dict (e.g., from DB query)
                df = pd.DataFrame(input_data)
                if df.empty:
                    raise ValueError("Ingested data is empty.")
                return StageResult(status=StageStatus.COMPLETED, data=df)

            else:
                raise TypeError(f"Unsupported input type for ingestion: {type(input_data)}")

        except Exception as e:
            logger.error(f"Ingestion failed: {e}")
            return StageResult(status=StageStatus.FAILED, error=str(e))


class ValidationStage(DataStage):
    """Data validation module ensuring data integrity and quality."""

    def __init__(self, required_columns: Optional[List[str]] = None, 
                 column_types: Optional[Dict[str, type]] = None,
                 allow_missing: bool = False):
        super().__init__("Validation")
        self.required_columns = required_columns or []
        self.column_types = column_types or {}
        self.allow_missing = allow_missing

    def execute(self, input_data: pd.DataFrame) -> StageResult:
        """Validate data for consistency, accuracy, completeness, and validity."""
        try:
            df = input_data.copy()

            # Check required columns
            missing_cols = [col for col in self.required_columns if col not in df.columns]
            if missing_cols:
                raise ValueError(f"Missing required columns: {missing_cols}")

            # Check column types
            for col, expected_type in self.column_types.items():
                if col in df.columns:
                    # Try to convert; if fails, validation fails
                    try:
                        df[col] = df[col].astype(expected_type)
                    except (ValueError, TypeError):
                        raise ValueError(f"Column '{col}' cannot be cast to {expected_type}")

            # Check completeness (no NaN in required columns)
            if not self.allow_missing:
                if self.required_columns:
                    missing_values = df[self.required_columns].isnull().any()
                    if missing_values.any():
                        raise ValueError(f"Missing values in required columns: {missing_values[missing_values].index.tolist()}")

            # Basic validity: no infinite values in numeric columns
            numeric_cols = df.select_dtypes(include=['number']).columns
            for col in numeric_cols:
                if not pd.api.types.is_numeric_dtype(df[col]):
                    continue
                if df[col].isin([float('inf'), float('-inf')]).any():
                    raise ValueError(f"Infinite values found in numeric column '{col}'")

            logger.info("Validation passed successfully.")
            return StageResult(status=StageStatus.COMPLETED, data=df)

        except Exception as e:
            logger.error(f"Validation failed: {e}")
            return StageResult(status=StageStatus.FAILED, error=str(e))


