class DataIngestionStage(DataStage[None, pd.DataFrame]):
    """Ingests data from various sources into a pandas DataFrame."""

    def __init__(self, source_path: Optional[str] = None, source_type: Optional[str] = None):
        self.source_path = source_path
        self.source_type = source_type or self._infer_source_type(source_path)

    def _infer_source_type(self, path: Optional[str]) -> str:
        if not path:
            return "csv"
        ext = os.path.splitext(path)[1].lower()
        mapping = {
            ".csv": "csv",
            ".xlsx": "excel",
            ".xls": "excel",
            ".json": "json",
        }
        return mapping.get(ext, "csv")

    def validate_input(self, input_data: None) -> bool:
        if not self.source_path:
            logger.warning("No source path provided; will attempt to use default or raise later.")
            return True
        if not os.path.exists(self.source_path):
            logger.error(f"Source file not found: {self.source_path}")
            return False
        return True

    def execute(self, input_data: None) -> StageResult[pd.DataFrame]:
        if not self.validate_input(input_data):
            return StageResult(status=StageStatus.FAILED, error="Input validation failed")

        try:
            logger.info(f"Ingesting data from {self.source_path} as {self.source_type}")
            if self.source_type == "csv":
                df = pd.read_csv(self.source_path)
            elif self.source_type in ("excel", "xls", "xlsx"):
                df = pd.read_excel(self.source_path)
            else:
                raise IngestionError(f"Unsupported source type: {self.source_type}")

            # Basic format validation
            if df.empty:
                logger.warning("Ingested DataFrame is empty.")
            if len(df.columns) == 0:
                raise IngestionError("No columns found in ingested data.")

            logger.info(f"Successfully ingested {len(df)} rows and {len(df.columns)} columns.")
            return StageResult(status=StageStatus.COMPLETED, data=df)

        except Exception as e:
            error_msg = f"Ingestion failed: {str(e)}"
            logger.error(error_msg)
            return StageResult(status=StageStatus.FAILED, error=error_msg)


